import java.util.*;

public class Main {
    // Universal method: Works seamlessly on List, Set, Queue, or any Collection!
    public static <T> void printCollectionSummary(String name, Collection<T> col) {
        System.out.println("[" + name + "] Size: " + col.size() + ", IsEmpty: " + col.isEmpty());
        System.out.print("Elements: ");
        for (T item : col) { // Uses Iterable contract!
            System.out.print(item + " ");
        }
        System.out.println();
    }

    public static void main(String[] args) {
        // 1. A List (ordered, permits duplicates)
        Collection<String> list = new ArrayList<>(Arrays.asList("A", "B", "A", "C"));

        // 2. A Set (unique, drops duplicate 'A')
        Collection<String> set = new HashSet<>(Arrays.asList("A", "B", "A", "C"));

        // 3. A Queue (FIFO processing order)
        Collection<String> queue = new ArrayDeque<>(Arrays.asList("First", "Second", "Third"));

        System.out.println("=== Demonstrating Polymorphic Collection Operations ===");
        printCollectionSummary("ArrayList", list);
        printCollectionSummary("HashSet", set);
        printCollectionSummary("ArrayDeque", queue);

        // Bulk operations: Set intersection (retainAll)
        list.retainAll(Collections.singleton("A"));
        System.out.println("\nAfter retainAll('A') on List: " + list);
    }
}

