public class Main {
    public static <T> void inspectCollection(String label, Collection<T> data) {
        System.out.println("=== " + label + " ===");
        System.out.println("Size: " + data.size());
        System.out.println("Empty: " + data.isEmpty());
        System.out.println("Contains 'Java': " + data.contains("Java"));
    }

    public static void main(String[] args) {
        Collection<String> list = new ArrayList<>(Arrays.asList("Java", "Kotlin"));
        Collection<String> set = new HashSet<>(Arrays.asList("Python", "Rust"));

        inspectCollection("Course List", list);
        inspectCollection("Unique Tools", set);
    }
}

