import java.util.*;

public class Main {
    public static void main(String[] args) {
        List<Integer> setA = Arrays.asList(1, 2, 3, 4, 5);
        List<Integer> setB = Arrays.asList(4, 5, 6, 7, 8);

        List<Integer> intersection = new ArrayList<>(setA);
        intersection.retainAll(setB);

        List<Integer> difference = new ArrayList<>(setA);
        difference.removeAll(setB);

        System.out.println("Intersection (A ∩ B): " + intersection);
        System.out.println("Difference (A - B): " + difference);
    }
}

